1	<!doctype html>
2	<html lang="en">
3	<head>
4	  <meta charset="utf-8">
5	  <meta name="viewport" content="width=device-width, initial-scale=1">
6	  <title>Trove — Save a link</title>
7	  <style>
8	    :root {
9	      --ink: #17231e;
10	      --muted: #68736d;
11	      --paper: #f5f2e9;
12	      --card: #fffdf7;
13	      --line: #d9d5ca;
14	      --green: #235d45;
15	      --green-dark: #174331;
16	      --green-pale: #e0eee5;
17	      --shadow: 0 18px 50px rgba(36, 48, 41, .10);
18	    }
19	
20	    * { box-sizing: border-box; }
21	    body {
22	      margin: 0;
23	      min-height: 100vh;
24	      color: var(--ink);
25	      background:
26	        radial-gradient(circle at 80% 12%, rgba(211, 226, 214, .65), transparent 28rem),
27	        var(--paper);
28	      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
29	    }
30	    button, input { font: inherit; }
31	    .shell { width: min(1080px, calc(100% - 48px)); margin: 0 auto; }
32	    header {
33	      height: 82px;
34	      display: flex;
35	      align-items: center;
36	      justify-content: space-between;
37	      border-bottom: 1px solid rgba(23, 35, 30, .10);
38	    }
39	    .brand { display: flex; align-items: center; gap: 11px; font-weight: 750; letter-spacing: -.02em; }
40	    .brand-mark {
41	      width: 34px; height: 34px; border-radius: 11px;
42	      display: grid; place-items: center; color: white; background: var(--green);
43	      box-shadow: 0 5px 14px rgba(35, 93, 69, .22);
44	    }
45	    .count { color: var(--muted); font-size: 14px; }
46	    main { padding: 82px 0 100px; }
47	    .eyebrow {
48	      display: inline-flex; align-items: center; gap: 8px;
49	      color: var(--green); font-size: 13px; font-weight: 750;
50	      text-transform: uppercase; letter-spacing: .11em;
51	    }
52	    .eyebrow::before { content: ""; width: 22px; height: 2px; background: currentColor; }
53	    h1 {
54	      max-width: 720px; margin: 17px 0 14px;
55	      font-family: Georgia, "Times New Roman", serif;
56	      font-size: clamp(42px, 6vw, 68px); line-height: .99; letter-spacing: -.045em;
57	      font-weight: 500;
58	    }
59	    .intro { max-width: 600px; margin: 0; color: var(--muted); font-size: 18px; line-height: 1.6; }
60	    .save-box {
61	      margin-top: 44px; padding: 12px; display: flex; gap: 10px;
62	      background: var(--card); border: 1px solid var(--line); border-radius: 18px;
63	      box-shadow: var(--shadow);
64	    }
65	    .url-wrap { flex: 1; display: flex; align-items: center; gap: 12px; padding-left: 11px; min-width: 0; }
66	    .url-wrap svg { flex: 0 0 auto; color: var(--muted); }
67	    input {
68	      width: 100%; min-width: 0; padding: 12px 0; border: 0; outline: 0;
69	      background: transparent; color: var(--ink); font-size: 16px;
70	    }
71	    button {
72	      padding: 14px 22px; border: 0; border-radius: 12px; color: white;
73	      background: var(--green); font-weight: 720; cursor: pointer;
74	      transition: transform .14s ease, background .14s ease;
75	    }
76	    button:hover { background: var(--green-dark); }
77	    button:active { transform: translateY(1px); }
78	    button:disabled { opacity: .65; cursor: default; }
79	    .hint { margin: 12px 0 0 15px; color: var(--muted); font-size: 13px; }
80	    .collection { margin-top: 70px; }
81	    .section-head { display: flex; align-items: baseline; justify-content: space-between; margin-bottom: 18px; }
82	    h2 { margin: 0; font-family: Georgia, serif; font-size: 27px; font-weight: 500; letter-spacing: -.025em; }
83	    .empty {
84	      min-height: 180px; display: grid; place-items: center; text-align: center;
85	      border: 1px dashed #c9c6bc; border-radius: 18px; color: var(--muted);
86	      background: rgba(255, 253, 247, .5);
87	    }
88	    .empty p { margin: 7px 0 0; font-size: 14px; }
89	    .saved-card {
90	      display: none; grid-template-columns: 72px 1fr auto; align-items: center; gap: 18px;
91	      padding: 20px; background: var(--card); border: 1px solid var(--line); border-radius: 18px;
92	      box-shadow: 0 9px 30px rgba(36, 48, 41, .07);
93	      animation: arrive .35s ease both;
94	    }
95	    .saved-card.visible { display: grid; }
96	    .thumb {
97	      width: 72px; height: 72px; border-radius: 14px; display: grid; place-items: center;
98	      background: #f1d9b7; font-family: Georgia, serif; font-size: 32px;
99	    }
100	    .card-title { margin: 0 0 6px; font-size: 17px; font-weight: 760; }
101	    .card-description { margin: 0 0 9px; color: var(--muted); font-size: 14px; }
102	    .domain { color: var(--green); font-size: 13px; font-weight: 650; }
103	    .saved-badge {
104	      align-self: start; padding: 7px 10px; color: var(--green); background: var(--green-pale);
105	      border-radius: 999px; font-size: 12px; font-weight: 750;
106	    }
107	    .toast {
108	      position: fixed; left: 50%; bottom: 28px; transform: translate(-50%, 20px);
109	      padding: 12px 17px; border-radius: 12px; background: var(--ink); color: white;
110	      font-size: 14px; opacity: 0; pointer-events: none; transition: .25s ease;
111	      box-shadow: 0 10px 30px rgba(0,0,0,.18);
112	    }
113	    .toast.show { opacity: 1; transform: translate(-50%, 0); }
114	    @keyframes arrive { from { opacity: 0; transform: translateY(10px); } }
115	    @media (max-width: 650px) {
116	      .shell { width: min(100% - 28px, 1080px); }
117	      main { padding-top: 55px; }
118	      .save-box { flex-direction: column; }
119	      button { width: 100%; }
120	      .saved-card { grid-template-columns: 56px 1fr; }
121	      .thumb { width: 56px; height: 56px; }
122	      .saved-badge { display: none; }
123	    }
124	  </style>
125	</head>
126	<body>
127	  <div class="shell" data-harness-ready="true">
128	    <header>
129	      <div class="brand"><span class="brand-mark">T</span> Trove</div>
130	      <div class="count" id="count">0 saved links</div>
131	    </header>
132	    <main>
133	      <span class="eyebrow">Your quiet corner of the web</span>
134	      <h1>Keep the good things you find.</h1>
135	      <p class="intro">Paste a web address. Trove fills in the useful details, so the link is ready to find when you need it.</p>
136	
137	      <form class="save-box" id="saveForm">
138	        <label class="url-wrap" aria-label="Web address">
139	          <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M10 13a5 5 0 0 0 7.1.1l2-2a5 5 0 0 0-7.1-7.1l-1.1 1.1"/><path d="M14 11a5 5 0 0 0-7.1-.1l-2 2A5 5 0 0 0 12 20l1.1-1.1"/></svg>
140	          <input id="url" type="url" value="https://www.seriouseats.com/how-to-make-perfect-risotto-recipe" required>
141	        </label>
142	        <button id="saveButton" type="submit">Save link</button>
143	      </form>
144	      <p class="hint">The title and description will be added automatically.</p>
145	
146	      <section class="collection" aria-live="polite">
147	        <div class="section-head"><h2>Recently saved</h2></div>
148	        <div class="empty" id="empty">
149	          <div><strong>No links yet</strong><p>Your first saved link will appear here.</p></div>
150	        </div>
151	        <article class="saved-card" id="savedCard">
152	          <div class="thumb">R</div>
153	          <div>
154	            <p class="card-title">How to Make Perfect Risotto</p>
155	            <p class="card-description">A step-by-step guide to creamy, deeply flavorful risotto, with tips for getting the texture just right.</p>
156	            <span class="domain">seriouseats.com</span>
157	          </div>
158	          <span class="saved-badge">Saved just now</span>
159	        </article>
160	      </section>
161	    </main>
162	  </div>
163	  <div class="toast" id="toast" role="status">Link saved with page details</div>
164	  <script>
165	    const form = document.querySelector('#saveForm');
166	    const button = document.querySelector('#saveButton');
167	    const empty = document.querySelector('#empty');
168	    const card = document.querySelector('#savedCard');
169	    const count = document.querySelector('#count');
170	    const toast = document.querySelector('#toast');
171	
172	    form.addEventListener('submit', (event) => {
173	      event.preventDefault();
174	      button.disabled = true;
175	      button.textContent = 'Getting details…';
176	      window.setTimeout(() => {
177	        empty.style.display = 'none';
178	        card.classList.add('visible');
179	        count.textContent = '1 saved link';
180	        button.textContent = 'Saved';
181	        toast.classList.add('show');
182	        window.setTimeout(() => toast.classList.remove('show'), 2200);
183	      }, 650);
184	    });
185	  </script>
186	</body>
187	</html>
