2	<html lang="en">
3	<head>
4	  <meta charset="utf-8">
5	  <meta name="viewport" content="width=device-width, initial-scale=1">
6	  <title>Trove — Correcting page details</title>
7	  <style>
8	    :root { --ink:#17231e; --muted:#68736d; --paper:#f5f2e9; --card:#fffdf7; --line:#d9d5ca; --green:#235d45; --pale:#e0eee5; }
9	    * { box-sizing:border-box; }
10	    body { margin:0; min-height:100vh; color:var(--ink); background:radial-gradient(circle at 80% 8%,#dce8dd,transparent 31rem),var(--paper); font-family:Inter,ui-sans-serif,system-ui,sans-serif; }
11	    button,input,textarea { font:inherit; }
12	    .shell { width:min(1200px,calc(100% - 44px)); margin:auto; padding-bottom:70px; }
13	    header { height:78px; display:flex; align-items:center; border-bottom:1px solid rgba(23,35,30,.1); font-weight:750; letter-spacing:-.02em; }
14	    .mark { width:34px; height:34px; margin-right:10px; display:grid; place-items:center; color:white; background:var(--green); border-radius:11px; }
15	    main { padding-top:52px; }
16	    h1 { margin:0; font:500 clamp(36px,5vw,54px)/1 Georgia,serif; letter-spacing:-.04em; }
17	    .lead { margin:13px 0 34px; color:var(--muted); font-size:17px; }
18	    .comparison { display:grid; grid-template-columns:1fr 1fr; gap:22px; }
19	    .version { overflow:hidden; background:rgba(255,253,247,.7); border:1px solid var(--line); border-radius:20px; box-shadow:0 16px 44px rgba(36,48,41,.08); }
20	    .version-head { padding:13px 18px; display:flex; justify-content:space-between; align-items:center; border-bottom:1px solid var(--line); color:var(--muted); font-size:13px; font-weight:700; }
21	    .dots { display:flex; gap:5px; }
22	    .dots i { width:7px; height:7px; border-radius:50%; background:#c9c6bc; }
23	    .app { min-height:430px; padding:25px; background:var(--card); }
24	    .app h2 { margin:0 0 6px; font:500 26px Georgia,serif; }
25	    .app-copy { margin:0 0 22px; color:var(--muted); font-size:13px; line-height:1.5; }
26	    .urlbar { display:flex; gap:8px; padding:8px; border:1px solid var(--line); border-radius:13px; background:white; }
27	    .urlbar input { flex:1; min-width:0; padding:9px; border:0; outline:0; color:var(--ink); background:transparent; font-size:12px; }
28	    button { border:0; border-radius:9px; padding:10px 14px; color:white; background:var(--green); font-weight:720; cursor:pointer; white-space:nowrap; }
29	    button.secondary { color:var(--green); background:var(--pale); }
30	    .details { display:none; margin-top:17px; padding:17px; border:1px solid var(--line); border-radius:14px; background:#fbfaf5; }
31	    .details.visible { display:block; animation:rise .25s ease both; }
32	    label { display:block; margin-bottom:13px; color:var(--muted); font-size:11px; font-weight:750; letter-spacing:.06em; text-transform:uppercase; }
33	    label input,label textarea { width:100%; margin-top:6px; padding:10px 11px; border:1px solid var(--line); border-radius:9px; color:var(--ink); background:white; font-size:13px; font-weight:500; letter-spacing:0; text-transform:none; outline:none; resize:none; }
34	    label input:focus,label textarea:focus { border-color:var(--green); box-shadow:0 0 0 3px rgba(35,93,69,.1); }
35	    .action-row { display:flex; justify-content:flex-end; align-items:center; gap:12px; }
36	    .note { color:var(--muted); font-size:11px; }
37	    .saved { display:none; margin-top:18px; padding:16px; grid-template-columns:48px 1fr auto; gap:12px; align-items:start; border:1px solid var(--line); border-radius:14px; background:#fbfaf5; }
38	    .saved.visible { display:grid; animation:rise .25s ease both; }
39	    .thumb { width:48px; height:48px; display:grid; place-items:center; border-radius:10px; background:#f1d9b7; font:24px Georgia,serif; }
40	    .saved h3 { margin:1px 0 5px; font-size:14px; }
41	    .saved p { margin:0 0 7px; color:var(--muted); font-size:11px; line-height:1.4; }
42	    .domain { color:var(--green); font-size:10px; font-weight:700; }
43	    .saved button { padding:7px 9px; font-size:11px; }
44	    .status { display:none; margin-top:10px; color:var(--green); font-size:12px; font-weight:700; }
45	    .status.visible { display:block; }
46	    @keyframes rise { from { opacity:0; transform:translateY(7px); } }
47	    @media(max-width:800px){ .comparison{grid-template-columns:1fr}.app{min-height:auto} }
48	  </style>
49	</head>
50	<body>
51	  <div class="shell" data-harness-ready="true">
52	    <header><span class="mark">T</span>Trove</header>
53	    <main>
54	      <h1>Make the details yours.</h1>
55	      <p class="lead">Two working versions of the same risotto bookmark.</p>
56	      <div class="comparison">
57	        <section class="version" id="beforeVersion">
58	          <div class="version-head"><span>VERSION A</span><span class="dots"><i></i><i></i><i></i></span></div>
59	          <div class="app">
60	            <h2>Save a link</h2>
61	            <p class="app-copy">Paste an address and review what Trove finds.</p>
62	            <div class="urlbar"><input aria-label="Web address in version A" value="https://www.seriouseats.com/how-to-make-perfect-risotto-recipe"><button id="getDetails">Get details</button></div>
63	            <div class="details" id="beforeDetails">
64	              <label>Title<input id="beforeTitle" value="How to Make Perfect Risotto"></label>
65	              <label>Description<textarea rows="3">A step-by-step guide to creamy, deeply flavorful risotto, with tips for getting the texture just right.</textarea></label>
66	              <div class="action-row"><span class="note">Not saved yet</span><button id="confirmBefore">Save link</button></div>
67	              <div class="status" id="beforeStatus">Saved with your changes</div>
68	            </div>
69	          </div>
70	        </section>
71	
72	        <section class="version" id="afterVersion">
73	          <div class="version-head"><span>VERSION B</span><span class="dots"><i></i><i></i><i></i></span></div>
74	          <div class="app">
75	            <h2>Save a link</h2>
76	            <p class="app-copy">Paste an address. Trove fills in the useful details.</p>
77	            <div class="urlbar"><input aria-label="Web address in version B" value="https://www.seriouseats.com/how-to-make-perfect-risotto-recipe"><button id="quickSave">Save link</button></div>
78	            <article class="saved" id="afterCard">
79	              <div class="thumb">R</div>
80	              <div><h3 id="afterHeading">How to Make Perfect Risotto</h3><p id="afterCopy">A step-by-step guide to creamy, deeply flavorful risotto, with tips for getting the texture just right.</p><span class="domain">seriouseats.com</span></div>
81	              <button class="secondary" id="editAfter">Edit</button>
82	            </article>
83	            <div class="details" id="afterDetails">
84	              <label>Title<input id="afterTitle" value="How to Make Perfect Risotto"></label>
85	              <label>Description<textarea id="afterDescription" rows="3">A step-by-step guide to creamy, deeply flavorful risotto, with tips for getting the texture just right.</textarea></label>
86	              <div class="action-row"><button id="confirmAfter">Save changes</button></div>
87	            </div>
88	            <div class="status" id="afterStatus">Changes saved</div>
89	          </div>
90	        </section>
91	      </div>
92	    </main>
93	  </div>
94	  <script>
95	    const $ = (selector) => document.querySelector(selector);
96	    $('#getDetails').onclick = () => $('#beforeDetails').classList.add('visible');
97	    $('#confirmBefore').onclick = () => $('#beforeStatus').classList.add('visible');
98	    $('#quickSave').onclick = () => { $('#afterCard').classList.add('visible'); $('#quickSave').textContent='Saved'; };
99	    $('#editAfter').onclick = () => { $('#afterCard').style.display='none'; $('#afterDetails').classList.add('visible'); };
100	    $('#confirmAfter').onclick = () => {
101	      $('#afterHeading').textContent=$('#afterTitle').value;
102	      $('#afterCopy').textContent=$('#afterDescription').value;
103	      $('#afterDetails').classList.remove('visible');
104	      $('#afterCard').style.display='grid';
105	      $('#afterStatus').classList.add('visible');
106	    };
107	  </script>
108	</body>
109	</html>
