6	  <title>Trove — Already saved</title>
7	  <style>
8	    :root{--ink:#17231e;--muted:#68736d;--paper:#f5f2e9;--card:#fffdf7;--line:#d9d5ca;--green:#235d45;--pale:#e0eee5}
