14	    .save-box input{flex:1;min-width:0;padding:12px;border:0;outline:0;color:var(--ink);background:transparent}.save-box button{padding:12px 19px;border:0;border-radius:10px;color:white;background:var(--green);font-weight:720;cursor:pointer}
