23	<body>
24	  <div class="shell" data-harness-ready="true">
25	    <header><div class="brand"><span class="mark">T</span>Trove</div><div class="count">1 saved link</div></header>
26	    <main>
27	      <h1>Keep the good things you find.</h1>
28	      <p class="lead">Paste an address and Trove will get it ready for you.</p>
29	      <form class="save-box" id="form"><input aria-label="Web address" value="https://www.seriouseats.com/how-to-make-perfect-risotto-recipe"><button>Get details</button></form>
30	      <div class="notice" id="notice" role="status">You already saved this link — here it is.</div>
31	      <section class="collection">
32	        <div class="section-head"><h2>Recently saved</h2><span>1 link</span></div>
33	        <article class="card" id="existing" tabindex="-1">
34	          <div class="thumb">R</div><div><h3>My perfect risotto guide</h3><p>A step-by-step guide to creamy, deeply flavorful risotto.</p><span class="domain">seriouseats.com</span></div><span class="date">Saved 3 days ago</span>
35	        </article>
36	      </section>
37	    </main>
38	  </div>
39	  <script>
40	    document.querySelector('#form').addEventListener('submit',(event)=>{
41	      event.preventDefault();
42	      const notice=document.querySelector('#notice');
43	      const existing=document.querySelector('#existing');
44	      notice.classList.add('visible');
45	      existing.classList.add('focused');
46	      existing.scrollIntoView({behavior:'smooth',block:'center'});
47	      existing.focus({preventScroll:true});
48	    });
49	  </script>
50	</body>
51	</html>
